pub(crate) struct Shared {
    pub families: Vec<(String, Outcomes)>,
    pub stop: Option<Stop>,
}

struct Ctx<'r, 'a> {
    run: &'r mut Run<'a>,
    outcomes: BTreeMap<String, Outcomes>,
    stop: Option<Stop>,
}

impl Ctx<'_, '_> {
    fn settle(
        &mut self,
        family: &str,
        spec: Spec,
        started: String,
        inputs: BTreeMap<String, Value>,
        found: Found,
    ) -> Result<()> {
        let outcomes = self.outcomes.entry(family.to_owned()).or_default();
        let stop = self
            .run
            .settle(family, spec, started, inputs, found, None, outcomes)?;
        if self.stop.is_none() {
            self.stop = stop;
        }
        Ok(())
    }

    fn block(&mut self, family: &str, spec: Spec, reason: &str) -> Result<()> {
        self.settle(
            family,
            spec,
            now_utc(),
            BTreeMap::new(),
            Found::blocked(reason),
        )
    }
}

fn state(j: &Value) -> String {
    j["academy"]["state"].as_str().unwrap_or("").to_owned()
}

fn account_hash(j: &Value) -> Option<String> {
    j["academy"]["accountId"].as_str().map(|a| {
        let digest = Sha256::digest(a.as_bytes());
        hex::encode(digest)
    })
}

fn learner(j: &Value) -> Value {
    j["learner"].clone()
}

fn public_inputs(run: &Run<'_>, family: &str) -> BTreeMap<String, Value> {
    let mut inputs = run.inputs(family, &[]);
    // Per-call receipts record redacted templates and assertion summaries.
    // An authentication receipt must not serialize the raw program again.
    inputs.retain(|name, _| !name.starts_with("call."));
    inputs
}

/// Starts the device sign-in and waits for the operator to approve it.
async fn sign_in(run: &Run<'_>, desk: &mut Desk, family: &str) -> Result<(Found, Option<String>)> {
    desk.send_json(json!({"kind": "startAcademySignIn"}))
        .await?;
    let awaiting = desk
        .until(desk.settle, |j| {
            matches!(state(j).as_str(), "awaitingApproval" | "failed")
        })
        .await;
    match awaiting {
        Some(j) if state(&j) == "awaitingApproval" => {}
        Some(j) => {
            return Ok((
                Found::failed("the sign-in could not start")
                    .with("academy", j["academy"]["failure"].clone()),
                None,
            ));
        }
        None => return Ok((Found::failed("the sign-in did not start in time"), None)),
    }
    // The core opens the verification page through the host; the operator
    // completes it there.
    desk.send_json(json!({"kind": "openAcademyVerification"}))
        .await?;
    let bound = run.operator_timeout(family);
    let (completed, step) = {
        let desk = &*desk;
        operator_step(
            run.operator.as_ref(),
            "academy-device-sign-in",
            "approve the Academy device sign-in with the designated test learner",
            None,
            bound,
            // A failed sign-in ends the wait; the core's state judges it.
            async || {
                desk.json()
                    .map(|j| matches!(state(&j).as_str(), "signedIn" | "failed"))
                    .unwrap_or(false)
            },
        )
        .await
    };
    let j = desk.json()?;
    let signed_in = completed && state(&j) == "signedIn";
    let mut found = Found::check(
        signed_in,
        "the operator approved the device sign-in and the core shows the learner signed in",
        if completed {
            "the device sign-in failed"
        } else {
            "the device sign-in was not completed within the bound"
        },
    )
    .with("state", json!(state(&j)))
    .with("failure", j["academy"]["failure"].clone())
    .with("vault", j["academy"]["vault"].clone());
    found.operator_step = Some(step);
    let hash = account_hash(&j);
    if let Some(h) = &hash {
        found = found
            .with("account_sha256", json!(h))
            .with("account_sha256_prefix", json!(&h[..16]));
    }
    Ok((found, hash))
}

/// One designated learner call: its label, procedure, kind and input.
struct Call {
    label: String,
    /// The workflows this call is evidence for, as its entry names them.
    workflows: &'static [&'static str],
    procedure: String,
    kind: ProcedureKind,
    input: Option<String>,
    /// What the hosted answer must hold, beyond answering with data.
    expect: Vec<Expect>,
}

/// Parses the family's `call.*` entries, each `<workflows> <procedure>
/// [<input>] ?? <expectation> [ && <expectation>]`: the workflow IDs (comma-separated, among those the family may
/// claim) the call is evidence for, the procedure, and its input. A call
/// counts only for the workflows it names.
fn program(run: &Run<'_>, family: &str) -> std::result::Result<Vec<Call>, String> {
    let Ok(f) = run.family(family) else {
        return Ok(Vec::new());
    };
    let allowed = claimable(family);
    let mut calls = Vec::new();
    let mut earlier = BTreeSet::new();
    for (key, value) in &f.nonsecret {
        let Some(label) = key.strip_prefix("call.") else {
            continue;
        };
        // Labels become receipt filenames. Keep them single, bounded path
        // components rather than letting manifest data select a write path.
        if label.is_empty()
            || label.len() > 96
            || !label
                .bytes()
                .all(|c| c.is_ascii_alphanumeric() || matches!(c, b'-' | b'_'))
        {
            return Err(
                "a call label must be 1-96 ASCII letters, digits, hyphens or underscores"
                    .to_owned(),
            );
        }
        let (value, expect) = match value.split_once(" ?? ") {
            Some((v, e)) => (v, e),
            None => (value.as_str(), ""),
        };
        let expect = expect
            .split(" && ")
            .filter(|e| !e.trim().is_empty())
            .map(|text| Expect::parse(text, &earlier))
            .collect::<std::result::Result<Vec<_>, _>>()
            .map_err(|e| format!("{key}: {e}"))?;
        let (tags, rest) = value
            .split_once(' ')
            .ok_or_else(|| format!("{key} names no workflow and procedure"))?;
        let mut workflows = Vec::new();
        for tag in tags.split(',').filter(|_| tags != "observe") {
            let w = allowed
                .iter()
                .find(|w| **w == tag)
                .ok_or_else(|| format!("{key}: {tag} is not a workflow {family} may claim"))?;
            workflows.push(*w);
        }
        let (procedure, input) = match rest.trim().split_once(' ') {
            Some((p, i)) => (p.to_owned(), Some(i.trim().to_owned())),
            None => (rest.trim().to_owned(), None),
        };
        let kind = LEARNER_PROCEDURES
            .iter()
            .find(|(p, _)| *p == procedure)
            .map(|(_, k)| *k)
            .ok_or_else(|| format!("{procedure} is not a learner procedure"))?;
        if tags == "observe" && kind == ProcedureKind::Mutation {
            return Err(format!(
                "{key}: observe is read-only and grants no workflow credit"
            ));
        }
        if kind == ProcedureKind::Mutation && !f.permitted_operations.contains(&procedure) {
            return Err(format!(
                "{procedure} changes learner state but is not a permitted operation of {family}"
            ));
        }
        if kind == ProcedureKind::Mutation && !account_designated(run, family) {
            return Err(format!(
                "{key}: a mutation requires expected_account_sha256 for the designated test learner"
            ));
        }
        if expect.is_empty() {
            return Err(format!("{key}: an explicit result expectation is required"));
        }
        if procedure == "progress.checkInline" && !expect.iter().any(Expect::is_grading_verdict) {
            return Err(format!(
                "{key}: inline grading requires /correct=true or /correct=false, not only a boolean shape"
            ));
        }
        if let Some(input) = &input {
            let value = serde_json::from_str::<Value>(input)
                .map_err(|_| format!("{key}: the input is not JSON"))?;
            validate_input(&value, &earlier).map_err(|e| format!("{key}: {e}"))?;
        }
        earlier.insert(label.to_owned());
        calls.push(Call {
            label: label.to_owned(),
            workflows: Box::leak(workflows.into_boxed_slice()),
            procedure,
            kind,
            input,
            expect,
        });
    }
    contracts::validate(&calls)?;
    Ok(calls)
}

/// A successful read is useful evidence, but cannot close an interactive row.
/// These checkpoints describe ordered minimums, not a substitute for each
/// call's designated result assertions or the broader native acceptance.
fn workflow_steps(workflow: &str) -> &'static [&'static str] {
    match workflow {
        "W53" => &["exam.start", "exam.submissionState", "certificate.mine"],
        "W65" => &[
            "shift.start",
            "shift.serve",
            "shift.answer",
            "shift.decide",
            "shift.debrief",
        ],
        "W66" => &[
            "certificate.mine",
            "progress.courseSummary",
            "progress.resetCourse",
            "progress.courseSummary",
            "certificate.mine",
        ],
        _ => &[],
    }
}

fn account_designated(run: &Run<'_>, family: &str) -> bool {
    run.nonsecret(family, "expected_account_sha256")
        .is_some_and(|h| {
            h.len() == 64
                && h.bytes()
                    .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
        })
}

fn result_found(result: &Value) -> Found {
    let kind = result["kind"].as_str().unwrap_or("");
    let mut found = Found::check(
        kind == "data",
        "the hosted procedure answered",
        "the hosted procedure did not answer with data",
    )
    .with("result", json!(kind))
    .with("http_status", result["httpStatus"].clone())
    .with("failure", result["failure"].clone())
    .with("outcome", result["outcome"].clone());
    if kind == "error" && result["outcome"] == "unknown" {
        found = found.stopping("a learner mutation may or may not have taken effect", true);
    }
    found
}

async fn call(
    desk: &mut Desk,
    procedure: &str,
    kind: ProcedureKind,
    input: Option<&str>,
) -> Result<Value> {
    let learner = learner(&desk.json()?);
    desk.academy(
        json!({"kind": "academyCall", "learner": learner, "procedure": procedure,
        "procedureKind": if kind == ProcedureKind::Mutation { "mutation" } else { "query" },
        "input": input}),
    )
    .await
}

fn leak(name: String) -> &'static str {
    Box::leak(name.into_boxed_str())
}

pub(crate) async fn run(run: &mut Run<'_>, families: &[String]) -> Result<Shared> {
    let mut ctx = Ctx {
        run,
        outcomes: BTreeMap::new(),
        stop: None,
    };
    let wants = |f: &str| families.iter().any(|x| x == f);
    let origin = FAMILIES
        .iter()
        .filter(|f| wants(f))
        .find_map(|f| ctx.run.nonsecret(f, "academy_origin"));
    let lead = FAMILIES.iter().copied().find(|f| wants(f)).unwrap_or("L11");
    let offline = if wants("L14") {
        Some(ctx.run.folder("offline")?)
    } else {
        None
    };
    let mut desk = ctx.run.desk(DeskOptions {
        offline_root: offline,
        academy_origin: origin.filter(|o| o.starts_with("https://")),
        image: wants("L13").then(|| AVATAR_PNG.to_vec()),
        ..DeskOptions::default()
    })?;

    let started = now_utc();
    let (found, account) = sign_in(ctx.run, &mut desk, lead).await?;
    let signed_in = found.outcome == "passed";
    let sign_in_family = if wants("L11") { "L11" } else { lead };
    ctx.settle(
        sign_in_family,
        SIGN_IN,
        started,
        public_inputs(ctx.run, sign_in_family),
        found,
    )?;
    if !signed_in {
        for family in families {
            let spec = Spec {
                id: leak(format!("{family}-after-sign-in")),
                workflows: &[],
            };
            ctx.block(family, spec, "the learner was not signed in")?;
        }
        return Ok(finish(ctx, families));
    }

    // A browser can silently approve as its existing account. A designated
    // identity must therefore be checked against the core's signed-in identity,
    // before any learner program or optional avatar mutation is dispatched.
    for family in families {
        if let Some(expected) = ctx.run.nonsecret(family, "expected_account_sha256")
            && (!account_designated(ctx.run, family) || account.as_deref() != Some(&expected))
        {
            let found = Found::blocked(
                "the signed-in Academy account does not match the designated learner",
            )
            .stopping(
                "unexpected Academy account; no learner program was sent",
                false,
            );
            ctx.settle(
                family,
                Spec {
                    id: leak(format!("{family}-account-binding")),
                    workflows: &[],
                },
                now_utc(),
                BTreeMap::new(),
                found,
            )?;
            desk.send_json(json!({"kind":"signOutAcademy"})).await?;
            return Ok(finish(ctx, families));
        }
    }

    if wants("L11") {
        let started = now_utc();
        let me = call(&mut desk, "desktop.me", ProcedureKind::Query, None).await?;
        // Academy's access check takes the courses to check (the designated
        // course, when there is one).
        let courses: Vec<String> = ctx.run.nonsecret("L14", "course_id").into_iter().collect();
        let input = json!({"json": {"courseIds": courses}}).to_string();
        let access = call(
            &mut desk,
            "desktop.access",
            ProcedureKind::Query,
            Some(&input),
        )
        .await?;
        let found = Found::check(
            me["kind"] == "data" && access["kind"] == "data",
            "protected learner procedures were admitted with the signed-in learner's token",
            "a protected learner procedure was not admitted",
        )
        .with("desktop.me", me["kind"].clone())
        .with("desktop.access", access["kind"].clone());
        ctx.settle(
            "L11",
            ADMISSION,
            started,
            public_inputs(ctx.run, "L11"),
            found,
        )?;
    }

    for family in ["L12", "L13", "L14"] {
        if !wants(family) || ctx.stop.is_some() {
            continue;
        }
        match program(ctx.run, family) {
            Err(e) => {
                let spec = Spec {
                    id: leak(format!("{family}-calls")),
                    workflows: &[],
                };
                ctx.block(family, spec, &e)?;
            }
            Ok(calls) => {
                if calls.is_empty() && family != "L14" {
                    let spec = Spec {
                        id: leak(format!("{family}-calls")),
                        workflows: &[],
                    };
                    ctx.block(
                        family,
                        spec,
                        &format!("{family} designates no call.* procedures"),
                    )?;
                }
                let mut answers: BTreeMap<String, Value> = BTreeMap::new();
                let mut failed_workflows = BTreeSet::new();
                let mut coverage: BTreeMap<&str, Vec<String>> = calls
                    .iter()
                    .flat_map(|c| c.workflows.iter().copied())
                    .filter(|w| !workflow_steps(w).is_empty())
                    .map(|w| (w, Vec::new()))
                    .collect();
                for designated in calls {
                    let cleanup = contracts::cleanup(&designated);
                    let Call {
                        label,
                        workflows,
                        procedure,
                        kind,
                        input,
                        expect,
                    } = designated;
                    if ctx.stop.is_some() {
                        break;
                    }
                    let spec = Spec {
                        id: leak(format!("{family}-call-{label}")),
                        workflows,
                    };
                    let started = now_utc();
                    let mut inputs = BTreeMap::new();
                    inputs.insert("procedure".to_owned(), json!(procedure));
                    // Record the designated template, never values copied out of
                    // a protected hosted answer into the outgoing request.
                    inputs.insert("input".to_owned(), receipt_input(&input));
                    if kind == ProcedureKind::Mutation
                        && !cleanup
                        && workflows.iter().any(|w| failed_workflows.contains(w))
                    {
                        ctx.settle(
                            family,
                            spec,
                            started,
                            inputs,
                            Found::blocked(
                                "an earlier checkpoint of this workflow failed; mutation not sent",
                            ),
                        )?;
                        continue;
                    }
                    let resolved = input
                        .as_deref()
                        .map(|text| {
                            let value = serde_json::from_str(text).expect("program validated JSON");
                            resolve_input(value, &answers).map(|value| value.to_string())
                        })
                        .transpose();
                    let input = match resolved {
                        Ok(input) if expect.iter().all(|e| e.ready(&answers)) => input,
                        _ => {
                            failed_workflows.extend(workflows.iter().copied());
                            ctx.settle(
                                family,
                                spec,
                                started,
                                inputs,
                                Found::blocked(
                                    "an earlier validated result is unavailable; call not sent",
                                ),
                            )?;
                            continue;
                        }
                    };
                    // Charged before it is sent: an exhausted budget sends nothing.
                    if let Err(e) = ctx.run.guard.spend(family, "calls", 1) {
                        let found = Found::blocked(e.clone())
                            .stopping(format!("unexpected cost: {e}"), false);
                        ctx.settle(family, spec, started, inputs, found)?;
                        break;
                    }
                    let result = call(&mut desk, &procedure, kind, input.as_deref()).await?;
                    let mut found = result_found(&result);
                    if found.outcome == "passed" {
                        if let Some(got) = answer(&result) {
                            let observed: Vec<Value> =
                                expect.iter().map(|e| e.observe(&got, &answers)).collect();
                            let passed = observed.iter().all(|o| o["passed"] == true);
                            found = Found::check(
                                passed,
                                "the hosted procedure answered and its result held",
                                "the hosted answer did not hold its designated expectations",
                            )
                            .with("assertions", json!(observed));
                            if passed {
                                answers.insert(label.clone(), got);
                                for workflow in workflows {
                                    if let Some(steps) = coverage.get_mut(workflow) {
                                        steps.push(procedure.clone());
                                    }
                                }
                            }
                        } else {
                            found = Found::failed(
                                "the hosted data response has no valid SuperJSON answer",
                            );
                        }
                    }
                    if kind == ProcedureKind::Mutation {
                        found.cleanup =
                            "synthetic coursework on a test account (owner-designated)".to_owned();
                    }
                    if found.outcome != "passed" {
                        failed_workflows.extend(workflows.iter().copied());
                    }
                    if cleanup {
                        if found.outcome == "passed" {
                            found.cleanup =
                                "the same Daily run was handed off at a completed stage boundary"
                                    .to_owned();
                        } else {
                            found.cleanup = "hand-off was not confirmed; the spent Daily run may remain active until Academy's stale sweep; reconciliation required".to_owned();
                            found = found.stopping(
                                "Daily hand-off was not confirmed; reconcile the active run",
                                true,
                            );
                        }
                    }
                    ctx.settle(family, spec, started, inputs, found)?;
                }
                for (workflow, completed) in coverage {
                    let required = workflow_steps(workflow);
                    let mut remaining = required.iter();
                    let mut next = remaining.next();
                    for procedure in &completed {
                        if next.is_some_and(|n| *n == procedure) {
                            next = remaining.next();
                        }
                    }
                    let found = Found::check(next.is_none() && !failed_workflows.contains(workflow),
                        "the interactive workflow's ordered checkpoints passed their result assertions",
                        "the interactive workflow is incomplete; successful reads do not close it")
                        .with("required_procedures", json!(required))
                        .with("validated_procedures", json!(completed));
                    ctx.settle(
                        family,
                        Spec {
                            id: leak(format!("{family}-workflow-{workflow}")),
                            workflows: Box::leak(vec![workflow].into_boxed_slice()),
                        },
                        now_utc(),
                        BTreeMap::new(),
                        found,
                    )?;
                }
            }
        }
    }

    if wants("L13") && ctx.stop.is_none() {
        let started = now_utc();
        let permitted = ctx
            .run
            .family("L13")
            .map(|f| {
                f.permitted_operations
                    .iter()
                    .any(|o| o == "settings.removeAvatar")
            })
            .unwrap_or(false);
        let found = if !account_designated(ctx.run, "L13") {
            Found::blocked(
                "an avatar mutation requires expected_account_sha256 for the designated test learner",
            )
        } else if !permitted {
            Found::blocked(
                "an avatar upload needs settings.removeAvatar among L13's permitted operations, to undo it",
            )
        } else if let Err(e) = ctx.run.guard.spend("L13", "calls", 2) {
            // The upload and its removal, charged before either is sent.
            Found::blocked(e.clone()).stopping(format!("unexpected cost: {e}"), false)
        } else {
            let learner = learner(&desk.json()?);
            let uploaded = desk
                .academy(json!({"kind": "uploadAvatar", "learner": learner}))
                .await?;
            let removed = call(
                &mut desk,
                "settings.removeAvatar",
                ProcedureKind::Mutation,
                None,
            )
            .await?;
            let mut found = Found::check(
                uploaded["kind"] == "data" && removed["kind"] == "data",
                "a synthetic avatar was bounded, re-encoded and uploaded, then removed",
                "the avatar upload or its removal did not complete",
            )
            .with("upload", uploaded["kind"].clone())
            .with("upload_failure", uploaded["failure"].clone())
            .with("remove", removed["kind"].clone());
            found.cleanup = "removed with settings.removeAvatar".to_owned();
            found
        };
        ctx.settle("L13", AVATAR, started, BTreeMap::new(), found)?;
    }

    if wants("L14") && ctx.stop.is_none() {
        l14(&mut ctx, &mut desk).await?;
    }

    if wants("L11") && ctx.stop.is_none() {
        let started = now_utc();
        let before = learner(&desk.json()?);
        desk.send_json(json!({"kind": "signOutAcademy"})).await?;
        let out = desk
            .until(desk.settle, |j| state(j) == "signedOut")
            .await
            .is_some();
        // The retired learner reference is refused by the core afterwards.
        let refused = desk
            .send_json(
                json!({"kind": "academyCall", "learner": before, "procedure": "desktop.me",
                "procedureKind": "query", "input": null}),
            )
            .await
            .is_err();
        let found = Found::check(
            out && refused,
            "signed out: the session was deleted, its refresh token revoked, and the old learner is refused",
            "sign-out did not retire the learner",
        );
        ctx.settle("L11", SIGN_OUT, started, BTreeMap::new(), found)?;

        let started = now_utc();
        let found = if ctx.run.nonsecret("L11", "second_account").as_deref() == Some("designated") {
            let (found, second) = sign_in(ctx.run, &mut desk, "L11").await?;
            let switched = found.outcome == "passed" && second.is_some() && second != account;
            let mut found = Found {
                outcome: if switched { "passed" } else { "failed" },
                detail: if switched {
                    "a second test learner signed in; the account changed and nothing of the first carried over".to_owned()
                } else {
                    "the second sign-in did not show a different account".to_owned()
                },
                ..found
            };
            desk.send_json(json!({"kind": "signOutAcademy"})).await?;
            found.cleanup = "signed out again".to_owned();
            found
        } else {
            Found::blocked("L11 designates no second_account for the account switch")
        };
        ctx.settle("L11", SWITCH, started, BTreeMap::new(), found)?;
    } else if ctx.stop.is_none() {
        desk.send_json(json!({"kind": "signOutAcademy"})).await?;
    }
    Ok(finish(ctx, families))
}

async fn l14(ctx: &mut Ctx<'_, '_>, desk: &mut Desk) -> Result<()> {
    let Some(course) = ctx.run.nonsecret("L14", "course_id") else {
        for spec in [DOWNLOAD, DRAFT, DENIAL] {
            ctx.block("L14", spec, "L14 designates no course_id")?;
        }
        return Ok(());
    };
    let started = now_utc();
    let learner_ref = learner(&desk.json()?);
    let downloaded = desk
        .academy(json!({"kind": "downloadCourse", "learner": learner_ref, "courseId": course}))
        .await?;
    let mut found = result_found(&downloaded);
    found.detail = if found.outcome == "passed" {
        "the client-safe course was downloaded under its lease and sealed for this account"
            .to_owned()
    } else {
        "the course could not be downloaded".to_owned()
    };
    found.cleanup = "removed at the end of the family".to_owned();
    let mut inputs = BTreeMap::new();
    inputs.insert("course_id".to_owned(), json!(course));
    ctx.settle("L14", DOWNLOAD, started, inputs.clone(), found)?;

    let started = now_utc();
    let found = match ctx.run.nonsecret("L14", "attempt_id") {
        None => Found::blocked("L14 designates no attempt_id"),
        Some(attempt) => {
            let base: u32 = ctx
                .run
                .nonsecret("L14", "base_version")
                .and_then(|b| b.parse().ok())
                .unwrap_or(0);
            let draft = "C25 synthetic local draft";
            // Lab work is a JSON object, as the learner page keeps it.
            let saved = desk
                .academy(
                    json!({"kind": "saveLocalDraft", "learner": learner_ref, "attemptId": attempt,
                    "baseVersion": base, "draft": json!({"c25": draft}).to_string()}),
                )
                .await?;
            let loaded = desk
                .academy(
                    json!({"kind": "loadLocalDraft", "learner": learner_ref, "attemptId": attempt}),
                )
                .await?;
            let kept = loaded["data"].as_str().is_some_and(|d| d.contains(draft));
            let _ = desk
                .academy(json!({"kind": "clearLocalDraft", "learner": learner_ref, "attemptId": attempt}))
                .await;
            let mut found = Found::check(
                saved["kind"] == "data" && kept,
                "the draft was sealed locally for this account and read back; nothing was submitted",
                "the local draft was not kept",
            )
            .with("save", json!({"kind": saved["kind"], "failure": saved["failure"]}))
            .with("load", json!({"kind": loaded["kind"], "failure": loaded["failure"]}));
            found.cleanup = "cleared from this Mac".to_owned();
            found
        }
    };
    ctx.settle("L14", DRAFT, started, inputs.clone(), found)?;

    // The operator changes the account's access; the core must then refuse.
    let started = now_utc();
    let found = if ctx.run.nonsecret("L14", "access_change").as_deref() != Some("designated") {
        Found::blocked("L14 designates no access_change the operator can make")
    } else {
        let bound = ctx.run.operator_timeout("L14");
        let course = course.clone();
        let denied = {
            let desk_ref = &mut *desk;
            let learner = learner_ref.clone();
            let mut last = Value::Null;
            let (done, step) = operator_step(
                ctx.run.operator.as_ref(),
                "academy-access-change",
                "remove the designated test learner's access to the designated course now",
                None,
                bound,
                async || {
                    tokio::time::sleep(std::time::Duration::from_secs(1)).await;
                    match desk_ref
                        .academy(json!({"kind": "downloadCourse", "learner": learner, "courseId": course}))
                        .await
                    {
                        Ok(r) => {
                            // Academy withdrew the course (no longer
                            // downloadable) or refused the learner.
                            let refused = (r["kind"] == "failed"
                                && r["failure"] == "notDownloadable")
                                || (r["kind"] == "error"
                                    && matches!(r["httpStatus"].as_u64(), Some(401 | 403 | 404)));
                            last = r;
                            refused
                        }
                        Err(_) => false,
                    }
                },
            )
            .await;
            (done, step, last)
        };
        let (done, step, last) = denied;
        let mut found = Found::check(
            done,
            "after the operator's access change, Academy refused the course and nothing stale was served",
            "Academy kept serving the course after the access change",
        )
        .with("last", json!({"kind": last["kind"], "failure": last["failure"], "http_status": last["httpStatus"]}));
        found.operator_step = Some(step);
        found
    };
    ctx.settle("L14", DENIAL, started, inputs, found)?;
    let _ = desk
        .academy(json!({"kind": "removeDownload", "learner": learner_ref, "courseId": course}))
        .await;
    Ok(())
}

fn finish(ctx: Ctx<'_, '_>, families: &[String]) -> Shared {
    let Ctx {
        mut outcomes, stop, ..
    } = ctx;
    Shared {
        families: families
            .iter()
            .map(|f| (f.clone(), outcomes.remove(f).unwrap_or_default()))
            .collect(),
        stop,
    }
}

//! Assertions and data dependencies for an operator-designated Academy program.
//! Hosted values stay in memory; receipts expose scalar verdicts or fingerprints.

use std::collections::{BTreeMap, BTreeSet};

use serde_json::{Value, json};

#[derive(Debug)]
pub(super) enum Expect {
    Kind(String, String),
    Equals(String, Value),
    Same(String, String, String),
    OneOf(String, Vec<Value>),
}

fn pointer_valid(pointer: &str) -> bool {
    if !pointer.is_empty() && !pointer.starts_with('/') {
        return false;
    }
    let mut chars = pointer.chars();
    while let Some(c) = chars.next() {
        if c == '~' && !matches!(chars.next(), Some('0' | '1')) {
            return false;
        }
    }
    true
}

fn reference_valid(label: &str, pointer: &str, earlier: &BTreeSet<String>) -> Result<(), String> {
    if !earlier.contains(label) {
        return Err("a reference must name an earlier call in the same family".to_owned());
    }
    if !pointer_valid(pointer) {
        return Err("invalid JSON pointer in call reference".to_owned());
    }
    Ok(())
}

impl Expect {
    pub fn parse(text: &str, earlier: &BTreeSet<String>) -> Result<Self, String> {
        let text = text.trim();
        let assertion = if let Some((ptr, rest)) = text.split_once(" in ") {
            let values: Vec<Value> = serde_json::from_str(rest)
                .map_err(|_| "membership expects a nonempty JSON array".to_owned())?;
            if values.is_empty() || values.iter().any(|v| !v.is_string()) {
                return Err("membership expects a nonempty array of strings".to_owned());
            }
            Self::OneOf(ptr.to_owned(), values)
        } else if let Some((ptr, rest)) = text.split_once('=') {
            if let Some(other) = rest.strip_prefix('@') {
                let (label, ptr2) = other
                    .find('/')
                    .map_or((other, ""), |i| (&other[..i], &other[i..]));
                reference_valid(label, ptr2, earlier)?;
                Self::Same(ptr.to_owned(), label.to_owned(), ptr2.to_owned())
            } else {
                Self::Equals(
                    ptr.to_owned(),
                    serde_json::from_str(rest)
                        .map_err(|_| "the expected value is not JSON".to_owned())?,
                )
            }
        } else {
            match text.rsplit_once(':') {
                Some((ptr, kind))
                    if [
                        "bool",
                        "array",
                        "number",
                        "object",
                        "string",
                        "nonempty-array",
                        "nonempty-string",
                        "positive-number",
                    ]
                    .contains(&kind) =>
                {
                    Self::Kind(ptr.to_owned(), kind.to_owned())
                }
                _ => return Err("not an expectation".to_owned()),
            }
        };
        if !pointer_valid(assertion.pointer()) {
            return Err("invalid JSON pointer in expectation".to_owned());
        }
        Ok(assertion)
    }

    fn pointer(&self) -> &str {
        match self {
            Self::Kind(p, _) | Self::Equals(p, _) | Self::Same(p, _, _) | Self::OneOf(p, _) => p,
        }
    }

    pub fn ready(&self, earlier: &BTreeMap<String, Value>) -> bool {
        match self {
            Self::Same(_, label, pointer) => earlier
                .get(label)
                .and_then(|v| v.pointer(pointer))
                .is_some(),
            _ => true,
        }
    }

    pub fn is_grading_verdict(&self) -> bool {
        matches!(self, Self::Equals(pointer, Value::Bool(_)) if pointer == "/correct")
    }

    pub fn equals(&self, pointer: &str, value: &Value) -> bool {
        matches!(self, Self::Equals(p, v) if p == pointer && v == value)
    }

    pub fn kind(&self, pointer: &str, kind: &str) -> bool {
        matches!(self, Self::Kind(p, k) if p == pointer && k == kind)
    }

    pub fn same(&self, pointer: &str, label: &str, earlier_pointer: &str) -> bool {
        matches!(self, Self::Same(p, l, ep) if p == pointer && l == label && ep == earlier_pointer)
    }

    pub fn graded_shift_outcome(&self) -> bool {
        match self {
            Self::Equals(p, v) => {
                p == "/outcome" && [json!("correct"), json!("incorrect")].contains(v)
            }
            Self::OneOf(p, values) => {
                p == "/outcome"
                    && values
                        .iter()
                        .all(|v| [json!("correct"), json!("incorrect")].contains(v))
            }
            _ => false,
        }
    }

    pub fn checks_number(&self, pointer: &str) -> bool {
        self.kind(pointer, "number")
            || self.kind(pointer, "positive-number")
            || matches!(self, Self::Equals(p, Value::Number(_)) if p == pointer)
    }

    /// Private strings/containers are summarized without reversible fingerprints.
    pub fn observe(&self, answer: &Value, earlier: &BTreeMap<String, Value>) -> Value {
        let actual = answer.pointer(self.pointer());
        let (passed, expected) = match self {
            Self::Kind(_, kind) => (
                actual.is_some_and(|v| match kind.as_str() {
                    "bool" => v.is_boolean(),
                    "array" => v.is_array(),
                    "number" => v.is_number(),
                    "object" => v.is_object(),
                    "string" => v.is_string(),
                    "nonempty-array" => v.as_array().is_some_and(|a| !a.is_empty()),
                    "nonempty-string" => v.as_str().is_some_and(|s| !s.is_empty()),
                    "positive-number" => v.as_f64().is_some_and(|n| n > 0.0),
                    _ => false,
                }),
                json!({"kind": kind}),
            ),
            Self::Equals(_, want) => (actual == Some(want), shown_value(Some(want))),
            Self::Same(_, label, pointer) => {
                let want = earlier.get(label).and_then(|v| v.pointer(pointer));
                (
                    actual.is_some() && actual == want,
                    json!({"call": label, "pointer": pointer, "value": shown_value(want)}),
                )
            }
            Self::OneOf(_, values) => (
                actual.is_some_and(|v| values.contains(v)),
                json!({"one_of": values.iter().map(|v| shown_value(Some(v))).collect::<Vec<_>>()}),
            ),
        };
        json!({"pointer": self.pointer(), "passed": passed,
            "actual": shown_value(actual), "expected": expected})
    }
}

fn input_reference(value: &serde_json::Map<String, Value>) -> Result<Option<(&str, &str)>, String> {
    if !value.contains_key("$call") {
        return Ok(None);
    }
    if value.len() != 2 {
        return Err("a call reference contains exactly $call and pointer".to_owned());
    }
    match (
        value["$call"].as_str(),
        value.get("pointer").and_then(Value::as_str),
    ) {
        (Some(label), Some(pointer)) => Ok(Some((label, pointer))),
        _ => Err("a call reference needs string $call and pointer fields".to_owned()),
    }
}

pub(super) fn validate_input(value: &Value, earlier: &BTreeSet<String>) -> Result<(), String> {
    match value {
        Value::Object(map) => {
            if let Some((label, pointer)) = input_reference(map)? {
                return reference_valid(label, pointer, earlier);
            }
            for v in map.values() {
                validate_input(v, earlier)?;
            }
        }
        Value::Array(values) => {
            for v in values {
                validate_input(v, earlier)?;
            }
        }
        _ => {}
    }
    Ok(())
}

/// Exact JSON objects are references; strings are never interpolated or evaluated.
pub(super) fn resolve_input(
    value: Value,
    earlier: &BTreeMap<String, Value>,
) -> Result<Value, String> {
    Ok(match value {
        Value::Object(map) => {
            if let Some((label, pointer)) = input_reference(&map)? {
                return earlier
                    .get(label)
                    .and_then(|v| v.pointer(pointer))
                    .cloned()
                    .ok_or_else(|| {
                        "an earlier validated result is unavailable; call not sent".to_owned()
                    });
            }
            Value::Object(
                map.into_iter()
                    .map(|(k, v)| Ok((k, resolve_input(v, earlier)?)))
                    .collect::<Result<_, String>>()?,
            )
        }
        Value::Array(values) => Value::Array(
            values
                .into_iter()
                .map(|v| resolve_input(v, earlier))
                .collect::<Result<_, _>>()?,
        ),
        v => v,
    })
}

/// The transport's SuperJSON envelope must really contain an answer. Missing
/// `json` and malformed JSON must never be converted into an asserted null.
pub(super) fn answer(result: &Value) -> Option<Value> {
    let data: Value = serde_json::from_str(result["data"].as_str()?).ok()?;
    data.get("json").cloned()
}

fn shown_value(value: Option<&Value>) -> Value {
    match value {
        None => json!({"present": false}),
        Some(v) if v.is_boolean() || v.is_number() || v.is_null() => {
            json!({"present": true, "value": v})
        }
        Some(v) => {
            let text = v.to_string();
            json!({"present": true, "bytes": text.len(),
                "array_len": v.as_array().map(Vec::len)})
        }
    }
}

/// Preserve the operator's references, but never publish authored answers.
pub(super) fn receipt_input(input: &Option<String>) -> Value {
    let Some(input) = input else {
        return Value::Null;
    };
    let Ok(mut value) = serde_json::from_str::<Value>(input) else {
        return Value::Null;
    };
    for pointer in ["/json/answer", "/json/values"] {
        if let Some(answer) = value.pointer_mut(pointer) {
            *answer = json!({"redacted":true});
        }
    }
    json!(value.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pointers_and_dependencies_are_validated_before_dispatch() {
        let earlier = BTreeSet::from(["01-before".to_owned()]);
        for text in [
            "/x=@future",
            "/x=@01-before/bad~",
            "bad=true",
            "/bad~2=true",
            ":unknown",
        ] {
            assert!(Expect::parse(text, &earlier).is_err(), "{text}");
        }
        assert!(Expect::parse("/a~1b~0c=@01-before", &earlier).is_ok());
        for input in [
            json!({"$call":"future", "pointer":""}),
            json!({"$call":"01-before"}),
            json!({"$call":"01-before", "pointer":"", "extra":true}),
        ] {
            assert!(validate_input(&input, &earlier).is_err());
        }
    }

    #[test]
    fn equality_does_not_confuse_missing_null_or_boolean_shape_with_a_verdict() {
        let earlier = BTreeSet::new();
        let empty = BTreeMap::new();
        let correct =
            Expect::parse("/correct=true", &earlier).expect("valid fixture assertion or reference");
        for response in [
            json!({}),
            json!({"correct":false}),
            json!({"correct":"true"}),
        ] {
            assert_eq!(correct.observe(&response, &empty)["passed"], false);
        }
        assert_eq!(
            correct.observe(&json!({"correct":true}), &empty)["passed"],
            true
        );
        let null =
            Expect::parse("/value=null", &earlier).expect("valid fixture assertion or reference");
        assert_eq!(null.observe(&json!({}), &empty)["passed"], false);
        assert_eq!(null.observe(&json!({"value":null}), &empty)["passed"], true);
        assert!(answer(&json!({"data":"{}"})).is_none());
        assert!(answer(&json!({"data":"not JSON"})).is_none());
        assert_eq!(
            answer(&json!({"data":"{\"json\":null}"})),
            Some(Value::Null)
        );
    }

    #[test]
    fn dependencies_preserve_json_types_and_values_never_enter_receipts() {
        let names = BTreeSet::from(["01-start".to_owned()]);
        let earlier = BTreeMap::from([(
            "01-start".to_owned(),
            json!({"id":"private-id", "order":2, "certs":[{"name":"Private Learner"}]}),
        )]);
        let input = json!({"json":{"id":{"$call":"01-start", "pointer":"/id"}, "order":{"$call":"01-start", "pointer":"/order"}}});
        validate_input(&input, &names).expect("valid fixture assertion or reference");
        assert_eq!(
            resolve_input(input, &earlier).expect("valid fixture assertion or reference"),
            json!({"json":{"id":"private-id", "order":2}})
        );
        let expect = Expect::parse("/certs=@01-start/certs", &names)
            .expect("valid fixture assertion or reference");
        let observed = expect.observe(&earlier["01-start"], &earlier);
        assert_eq!(observed["passed"], true);
        assert!(!observed.to_string().contains("Private Learner"));
        assert!(
            !Expect::parse("/certs=@01-start/certs", &names)
                .expect("valid fixture assertion or reference")
                .ready(&BTreeMap::new())
        );
        assert!(
            resolve_input(json!({"$call":"01-start", "pointer":"/missing"}), &earlier).is_err()
        );
        assert_eq!(
            Expect::parse(":nonempty-array", &names)
                .expect("valid fixture assertion or reference")
                .observe(&json!([]), &earlier)["passed"],
            false
        );
    }

    #[test]
    fn membership_accepts_only_the_designated_graded_outcomes() {
        let expected = Expect::parse("/outcome in [\"correct\",\"incorrect\"]", &BTreeSet::new())
            .expect("membership");
        for (value, passes) in [
            ("correct", true),
            ("incorrect", true),
            ("ungraded", false),
            ("breached", false),
        ] {
            assert_eq!(
                expected.observe(&json!({"outcome":value}), &BTreeMap::new())["passed"],
                passes
            );
        }
        for invalid in ["/outcome in []", "/outcome in [true]", "/outcome in null"] {
            assert!(Expect::parse(invalid, &BTreeSet::new()).is_err());
        }
        let private =
            Expect::parse("/name=\"Private Learner\"", &BTreeSet::new()).expect("literal");
        let receipt = private.observe(&json!({"name":"Private Learner"}), &BTreeMap::new());
        assert!(!receipt.to_string().contains("Private Learner"));
        assert!(!receipt.to_string().contains("sha256"));
    }

    #[test]
    fn receipt_templates_and_membership_never_publish_authored_answers() {
        let input=Some(json!({"json":{"questionId":"q-1","answer":"PRIVATE-ANSWER","values":["PRIVATE-CHOICE"]}}).to_string());
        let recorded = receipt_input(&input).to_string();
        assert!(!recorded.contains("PRIVATE-ANSWER"));
        assert!(!recorded.contains("PRIVATE-CHOICE"));
        assert!(recorded.contains("questionId"));
        let expect =
            Expect::parse("/name in [\"PRIVATE-NAME\"]", &BTreeSet::new()).expect("membership");
        let recorded = expect
            .observe(&json!({"name":"PRIVATE-NAME"}), &BTreeMap::new())
            .to_string();
        assert!(!recorded.contains("PRIVATE-NAME"));
    }
}
//! Minimum evidence contracts for the interactive Academy qualification rows.
//! Reject weak plans before dispatch; private manifests choose test data, not
//! whether a boolean shape is enough to prove a destructive reset worked.

use serde_json::{Value, json};

use super::Call;

fn input(call: &Call) -> Value {
    call.input
        .as_deref()
        .and_then(|s| serde_json::from_str(s).ok())
        .unwrap_or(Value::Null)
}

fn reference(call: &Call, pointer: &str, label: &str, source: &str) -> bool {
    input(call).pointer(pointer) == Some(&json!({"$call": label, "pointer": source}))
}

fn equals(call: &Call, pointer: &str, value: Value) -> bool {
    call.expect.iter().any(|e| e.equals(pointer, &value))
}

fn kind(call: &Call, pointer: &str, kind: &str) -> bool {
    call.expect.iter().any(|e| e.kind(pointer, kind))
}

fn same(call: &Call, pointer: &str, label: &str, source: &str) -> bool {
    call.expect.iter().any(|e| e.same(pointer, label, source))
}

/// Only an explicitly scoped hand-off may proceed after a failed checkpoint.
/// The normal reference, account and budget checks still apply.
pub(super) fn cleanup(call: &Call) -> bool {
    call.procedure == "shift.decide" && input(call)["json"]["choice"] == "hand_off"
}

pub(super) fn validate(calls: &[Call]) -> Result<(), String> {
    for call in calls {
        let required = match call.procedure.as_str() {
            "progress.resetCourse" => Some("W66"),
            "exam.start" => Some("W53"),
            "shift.start" | "shift.serve" | "shift.answer" | "shift.decide" => Some("W65"),
            _ => None,
        };
        if required.is_some_and(|workflow| !call.workflows.contains(&workflow)) {
            return Err(format!(
                "{}: the procedure requires its interactive workflow contract",
                call.label
            ));
        }
    }
    for workflow in ["W53", "W65", "W66"] {
        let row: Vec<&Call> = calls
            .iter()
            .filter(|c| c.workflows.contains(&workflow))
            .collect();
        if row.is_empty() {
            continue;
        }
        let unique: &[(&str, usize)] = match workflow {
            "W53" => &[("exam.start", 1), ("exam.submissionState", 1)],
            "W65" => &[
                ("shift.start", 1),
                ("shift.decide", 1),
                ("shift.debrief", 1),
            ],
            "W66" => &[
                ("progress.resetCourse", 1),
                ("progress.courseSummary", 2),
                ("certificate.mine", 2),
            ],
            _ => &[],
        };
        if unique.iter().any(|(procedure, count)| {
            row.iter().filter(|c| c.procedure == *procedure).count() > *count
        }) {
            return Err(format!(
                "{workflow}: duplicate critical checkpoints are not permitted"
            ));
        }
        let mut iter = row.iter().copied();
        let mut ordered = Vec::new();
        for procedure in super::workflow_steps(workflow) {
            ordered.push(iter.find(|c| c.procedure == *procedure).ok_or_else(|| {
                format!("{workflow}: the program lacks ordered interactive checkpoints")
            })?);
        }
        let valid = match workflow {
            "W53" => exam(&ordered),
            "W65" => shift(&row, &ordered),
            "W66" => reset(&ordered),
            _ => false,
        };
        if !valid {
            return Err(format!(
                "{workflow}: the program lacks required outcome assertions or identity references; see academy-2.1-follow-up.md"
            ));
        }
    }
    Ok(())
}

fn exam(steps: &[&Call]) -> bool {
    let (start, state, certificates) = (steps[0], steps[1], steps[2]);
    kind(start, "/attemptId", "nonempty-string")
        && kind(start, "/deadline", "nonempty-string")
        && kind(start, "/timeLimitSeconds", "positive-number")
        && reference(state, "/json/attemptId", &start.label, "/attemptId")
        && same(state, "/attemptId", &start.label, "/attemptId")
        && equals(state, "/status", json!("in-progress"))
        && (kind(certificates, "", "array") || kind(certificates, "", "nonempty-array"))
}

fn shift(row: &[&Call], steps: &[&Call]) -> bool {
    let start = steps[0];
    if input(start)["json"]["daily"] != true
        || !kind(start, "/shiftId", "nonempty-string")
        || !equals(start, "/alertsAnswered", json!(0))
        || !equals(start, "/atBoundary", json!(false))
    {
        return false;
    }
    let mut served = Vec::new();
    for call in row {
        if !call.procedure.starts_with("shift.") || call.procedure == "shift.start" {
            continue;
        }
        // These other read procedures do not take a shift ID.
        if [
            "shift.daily",
            "shift.dailyBoard",
            "shift.history",
            "shift.eligibility",
            "shift.getActive",
            "shift.dailyGhost",
            "shift.yesterday",
        ]
        .contains(&call.procedure.as_str())
        {
            continue;
        }
        if !reference(call, "/json/shiftId", &start.label, "/shiftId") {
            return false;
        }
        let valid = match call.procedure.as_str() {
            "shift.serve" => {
                served.push(*call);
                same(call, "/shift/shiftId", &start.label, "/shiftId")
                    && call
                        .expect
                        .iter()
                        .any(|e| e.checks_number("/shift/alertOrder"))
                    && equals(call, "/breachResolved", json!(false))
            }
            "shift.answer" => {
                served.last().is_some_and(|serve| {
                    reference(call, "/json/order", &serve.label, "/shift/alertOrder")
                }) && call.expect.iter().any(|e| e.graded_shift_outcome())
            }
            "shift.decide" => {
                cleanup(call)
                    && same(call, "/shiftId", &start.label, "/shiftId")
                    && equals(call, "/status", json!("handed_off"))
            }
            "shift.debrief" => {
                kind(call, "/themes", "nonempty-array") && kind(call, "/links", "array")
            }
            _ => true,
        };
        if !valid {
            return false;
        }
    }
    true
}

fn reset(steps: &[&Call]) -> bool {
    let (certs, before, reset, after, certs_after) =
        (steps[0], steps[1], steps[2], steps[3], steps[4]);
    let course = input(before)["json"]["courseId"].clone();
    if !course.as_str().is_some_and(|c| !c.is_empty())
        || input(reset)["json"]["courseId"] != course
        || input(after)["json"]["courseId"] != course
    {
        return false;
    }
    let counts = ["units", "quizzes", "labs", "objectives"];
    kind(certs, "", "nonempty-array")
        && equals(before, "/hasProgress", json!(true))
        && counts
            .iter()
            .any(|c| kind(before, &format!("/{c}"), "positive-number"))
        && counts.iter().all(|c| {
            let pointer = format!("/{c}");
            (kind(before, &pointer, "number") || kind(before, &pointer, "positive-number"))
                && same(reset, &format!("/cleared/{c}"), &before.label, &pointer)
                && equals(after, &pointer, json!(0))
        })
        && equals(after, "/hasProgress", json!(false))
        && same(certs_after, "", &certs.label, "")
}

