        // The upload and its removal, charged before either is sent.
        Found::blocked(e.clone()).stopping(format!("unexpected cost: {e}"), false)
    } else {
        let learner = learner(&desk.json()?);
        let uploaded = desk
            .academy(json!({"kind": "uploadAvatar", "learner": learner}))
            .await?;
        let removed = call(
